List<string> transactions; // \u4EA4\u6613\u8BB0\u5F55\n\n        // ========== \u6784\u9020\u65B9\u6CD5 ==========\n        public BankAccount(string accountNumber, string holderName)\n        {\n            this.accountNumber = accountNumber;\n            this.holderName = holderName;\n            this.balance = 0;\n            this.createDate = DateTime.Now;\n            this.transactions = new List<string>();\n            \n            // \u8BB0\u5F55\u5F00\u6237\u4EA4\u6613\n            RecordTransaction($"\u5F00\u6237\uFF0C\u521D\u59CB\u4F59\u989D: \xa50.00");\n        }\n\n        // ========== \u65B9\u6CD5 ==========\n        \n        // \u5B58\u6B3E\n        public void Deposit(decimal amount)\n        {\n            if (amount <= 0)\n            {\n                Console.WriteLine("\u5B58\u6B3E\u91D1\u989D\u5FC5\u987B\u5927\u4E8E0\uFF01");\n                return;\n            }\n            \n            balance += amount;\n            RecordTransaction($"\u5B58\u6B3E: +\xa5{amount:F2}\uFF0C\u4F59\u989D: \xa5{balance:F2}");\n            Console.WriteLine($"\u5B58\u6B3E\u6210\u529F\uFF01\u5B58\u5165 \xa5{amount:F2}");\n        }\n\n        // \u53D6\u6B3E\n        public bool Withdraw(decimal amount)\n        {\n            if (amount <= 0)\n            {\n                Console.WriteLine("\u53D6\u6B3E\u91D1\u989D\u5FC5\u987B\u5927\u4E8E0\uFF01");\n                return false;\n            }\n            \n            if (amount > balance)\n            {\n                Console.WriteLine($"\u4F59\u989D\u4E0D\u8DB3\uFF01\u5F53\u524D\u4F59\u989D: \xa5{balance:F2}\uFF0C\u9700\u8981: \xa5{amount:F2}");\n                return false;\n            }\n            \n            balance -= amount;\n            RecordTransaction($"\u53D6\u6B3E: -\xa5{amount:F2}\uFF0C\u4F59\u989D: \xa5{balance:F2}");\n            Console.WriteLine($"\u53D6\u6B3E\u6210\u529F\uFF01\u53D6\u51FA \xa5{amount:F2}");\n            return true;\n        }\n\n        // \u67E5\u8BE2\u4F59\u989D\n        public decimal GetBalance()\n        {\n            return balance;\n        }\n\n        // \u6253\u5370\u8D26\u6237\u4FE1\u606F\n        public void PrintInfo()\n        {\n            Console.WriteLine("\\n========== \u8D26\u6237\u4FE1\u606F ==========");\n            Console.WriteLine($"\u8D26\u6237\u53F7: {accountNumber}");\n            Console.WriteLine($"\u6301\u6709\u4EBA: {holderName}");\n            Console.WriteLine($"\u5F53\u524D\u4F59\u989D: \xa5{balance:F2}");\n            Console.WriteLine($"\u5F00\u6237\u65E5\u671F: {createDate:yyyy-MM-dd HH:mm}");\n            Console.WriteLine("==============================\\n");\n        }\n\n        // \u6253\u5370\u4EA4\u6613\u8BB0\u5F55\n        public void PrintTransactions()\n        {\n            Console.WriteLine("\\n========== \u4EA4\u6613\u8BB0\u5F55 ==========");\n            if (transactions.Count == 0)\n            {\n                Console.WriteLine("\u6682\u65E0\u4EA4\u6613\u8BB0\u5F55");\n            }\n            else\n            {\n                foreach (var transaction in transactions)\n                {\n                    Console.WriteLine(transaction);\n                }\n            }\n            Console.WriteLine("==============================\\n");\n        }\n\n        // \u8BA1\u7B97\u5229\u606F\uFF08\u5E74\u5229\u73873%\uFF0C\u8BA1\u7B97\u672C\u6708\u5229\u606F\uFF09\n        public void CalculateInterest()\n        {\n            decimal monthlyRate = 0.03m / 12; // \u6708\u5229\u7387\n            decimal interest = balance * monthlyRate;\n            balance += interest;\n            RecordTransaction($"\u5229\u606F\u7ED3\u7B97: +\xa5{interest:F2}\uFF0C\u4F59\u989D: \xa5{balance:F2}");\n            Console.WriteLine($"\u5229\u606F\u5DF2\u7ED3\u7B97\uFF01\u83B7\u5F97\u5229\u606F: \xa5{interest:F2}");\n        }\n\n        // \u79C1\u6709\u65B9\u6CD5\uFF1A\u8BB0\u5F55\u4EA4\u6613\n        private void RecordTransaction(string description)\n        {\n            string record = $"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] {description}";\n            transactions.Add(record);\n        }\n    }\n\n    // \u7A0B\u5E8F\u5165\u53E3\n    class Program\n    {\n        static void Main(string[] args)\n        {\n            Console.WriteLine("=== \u6B22\u8FCE\u4F7F\u7528\u7B80\u6613\u94F6\u884C\u8D26\u6237\u7CFB\u7EDF ===\\n");\n            \n            // \u521B\u5EFA\u8D26\u6237\n            Console.Write("\u8BF7\u8F93\u5165\u8D26\u6237\u53F7: ");\n            string accNum = Console.ReadLine();\n            Console.Write("\u8BF7\u8F93\u5165\u6301\u6709\u4EBA\u59D3\u540D: ");\n            string name = Console.ReadLine();\n            \n            BankAccount myAccount = new BankAccount(accNum, name);\n            Console.WriteLine("\\n\u8D26\u6237\u521B\u5EFA\u6210\u529F\uFF01\\n");\n\n            // \u4E3B\u83DC\u5355\u5FAA\u73AF\n            bool running = true;\n            while (running)\n            {\n                Console.WriteLine("\u8BF7\u9009\u62E9\u64CD\u4F5C\uFF1A");\n                Console.WriteLine("1. \u5B58\u6B3E");\n                Console.WriteLine("2. \u53D6\u6B3E");\n                Console.WriteLine("3. \u67E5\u8BE2\u4F59\u989D");\n                Console.WriteLine("4. \u67E5\u770B\u8D26\u6237\u4FE1\u606F");\n                Console.WriteLine("5. \u67E5\u770B\u4EA4\u6613\u8BB0\u5F55");\n                Console.WriteLine("6. \u7ED3\u7B97\u5229\u606F");\n                Console.WriteLine("0. \u9000\u51FA");\n                Console.Write("\\n> ");\n                \n                string choice = Console.ReadLine();\n                Console.WriteLine();\n\n                switch (choice)\n                {\n                    case "1":\n                        Console.Write("\u8BF7\u8F93\u5165\u5B58\u6B3E\u91D1\u989D: ");\n                        if (decimal.TryParse(Console.ReadLine(), out decimal depositAmount))\n                        {\n                            myAccount.Deposit(depositAmount);\n                        }\n                        else\n                        {\n                            Console.WriteLine("\u8F93\u5165\u65E0\u6548\uFF01");\n                        }\n                        break;\n\n                    case "2":\n                        Console.Write("\u8BF7\u8F93\u5165\u53D6\u6B3E\u91D1\u989D: ");\n                        if (decimal.TryParse(Console.ReadLine(), out decimal withdrawAmount))\n                        {\n                            myAccount.Withdraw(withdrawAmount);\n                        }\n                        else\n                        {\n                            Console.WriteLine("\u8F93\u5165\u65E0\u6548\uFF01");\n                        }\n                        break;\n\n                    case "3":\n                        Console.WriteLine($"\u5F53\u524D\u4F59\u989D: \xa5{myAccount.GetBalance():F2}\\n");\n                        break;\n\n                    case "4":\n                        myAccount.PrintInfo();\n                        break;\n\n                    case "5":\n                        myAccount.PrintTransactions();\n                        break;\n\n                    case "6":\n                        myAccount.CalculateInterest();\n                        break;\n\n                    case "0":\n                        running = false;\n                        Console.WriteLine("\u611F\u8C22\u4F7F\u7528\uFF0C\u518D\u89C1\uFF01");\n                        break;\n\n                    default:\n                        Console.WriteLine("\u65E0\u6548\u9009\u9879\uFF0C\u8BF7\u91CD\u65B0\u9009\u62E9\u3002\\n");\n                        break;\n                }\n                \n                if (running)\n                {\n                    Console.WriteLine("\u6309\u4EFB\u610F\u952E\u7EE7\u7EED...");\n                    Console.ReadKey();\n                    Console.Clear();\n                }\n            }\n        }\n    }\n}\n'})})}function d(n={}){let{wr